\section{Introduction}

\subsection{Setting and notation}
Fix $n\ge2$ and write $\zeta_n = e^{-2\pi i/n}$, a primitive $n$-th root of unity.  For
$f:\Zn\to\CC$ the \emph{discrete Fourier transform} is
\[
  \hat f(k) \;=\; \sum_{x\in\Zn} \zeta_n^{\,\overline k\,\overline x} f(x),
\]
where $\overline y\in\{0,\dots,n-1\}$ denotes the canonical representative.  The \emph{support} is
$\supp f = \{x : f(x)\neq0\}$, and $f$ is \emph{$k$-sparse} if $|\supp f|\le k$.  Writing
$M_{k,x} = \zeta_n^{\overline k\overline x}$ for the $n\times n$ Fourier matrix, $\hat f = Mf$ and
$M\overline M^{\,T} = nI$, so the transform is invertible.

\subsection{The two uncertainty principles}
The classical Donoho--Stark bound holds for every modulus $n$ and every nonzero $f$:
\begin{equation}\label{eq:mult}
  |\supp f|\cdot|\supp\hat f| \;\ge\; n .
\end{equation}
For prime moduli a strictly stronger additive bound holds.

\begin{theoremletter}[Additive uncertainty principle]\label{thm:A}
Let $p$ be prime and $f:\Zp\to\CC$ nonzero.  Then
\[
  |\supp f| + |\supp\hat f| \;\ge\; p+1 .
\]
\end{theoremletter}

Theorem~\ref{thm:A} implies \eqref{eq:mult}: if $\alpha,\beta\ge1$ and $\alpha+\beta\ge P+1$ then
$\alpha\beta \ge \alpha+\beta-1 \ge P$, since $(\alpha-1)(\beta-1)\ge0$.  The converse fails.

\begin{proposition}[Strict strengthening]
For $p = 13$ the pair $|\supp f| = |\supp\hat f| = 4$ satisfies the multiplicative bound
$4\cdot4 = 16 \ge 13$, yet no nonzero $f:\ZZ/13\ZZ\to\CC$ realises it, because $4+4 = 8 < 14$.
\end{proposition}

The two statements differ most in the balanced regime $\alpha\approx\beta\approx\sqrt p$.

\section{Chebotarev's theorem on the minors of the prime Fourier matrix}

\begin{theorem}[Chebotarev, 1926]\label{thm:cheb}
Let $p$ be prime, $\zeta$ a primitive $p$-th root of unity, $k\ge0$, and let $a_1,\dots,a_k$ and
$b_1,\dots,b_k$ be pairwise distinct elements of $\{0,\dots,p-1\}$.  Then
\[
  \det\big(\zeta^{\,a_ib_j}\big)_{1\le i,j\le k} \;\neq\; 0 .
\]
\end{theorem}

Equivalently: every square submatrix of the $p\times p$ Fourier matrix is invertible
(\emph{total nonsingularity}).  Primality is essential: for $n=4$, $\zeta = i$, the block with rows
and columns $\{0,2\}$ is the singular all-ones matrix $\left(\begin{smallmatrix}1&1\\1&1\end{smallmatrix}\right)$.

\subsection{Frenkel's proof}
Fix $a,b$ as above and set
\[
  F(X) = \det\big(X^{a_ib_j}\big)\in\ZZ[X],\qquad G(X) = F(X+1),
\]
\[
  N = 0+1+\dots+(k-1) = \binom k2,\qquad \sfac(k) = \prod_{j=0}^{k-1} j!,\qquad
  V(a) = \prod_{i<j}(a_j-a_i).
\]

\begin{lemma}\label{lem:binom}
For every $d\ge0$, $\;G_d := [X^d]G(X) = \sum_{\sigma\in S_k}\sgn(\sigma)\binom{s_\sigma}{d}$, where
$s_\sigma = \sum_i a_{\sigma(i)}b_i$.
\end{lemma}

\begin{proof}
By the Leibniz formula $G(X) = \sum_\sigma \sgn(\sigma)\prod_i(X+1)^{a_{\sigma(i)}b_i}
= \sum_\sigma\sgn(\sigma)(X+1)^{s_\sigma}$; extract the coefficient of $X^d$.
\end{proof}

Define the \emph{alternating power sums} $T_r = \sum_\sigma \sgn(\sigma)s_\sigma^{\,r}$, and let
$D_d(X) = X(X-1)\cdots(X-d+1) = \sum_{r\le d}c_{d,r}X^r$ be the falling factorial, monic of degree
$d$, so that $d!\binom yd = D_d(y)$ for integers $y$.

\begin{lemma}\label{lem:falling}
For every $d\ge0$, $\;d!\,G_d = \sum_{r=0}^{d}c_{d,r}T_r$.
\end{lemma}

\begin{proof}
Multiply Lemma~\ref{lem:binom} by $d!$, substitute $d!\binom{s_\sigma}{d} = \sum_r c_{d,r}s_\sigma^r$
and exchange the finite sums.
\end{proof}

\begin{lemma}[Multinomial expansion]\label{lem:multi}
For every $r\ge0$,
\[
  T_r \;=\; \sum_{\substack{m:\{1,\dots,k\}\to\ZZ_{\ge0}\\ \sum_i m_i = r}}
  \binom{r}{m}\Big(\prod_i b_i^{\,m_i}\Big)\det\big(a_i^{\,m_j}\big)_{i,j}.
\]
\end{lemma}

\begin{proof}
Expand $s_\sigma^r$ multinomially, sum over $\sigma$ with signs, and recognise
$\sum_\sigma\sgn(\sigma)\prod_i a_{\sigma(i)}^{m_i}$ as the Leibniz expansion of
$\det(a_i^{m_j})$.
\end{proof}

\begin{lemma}\label{lem:noninj}
If $m$ is not injective then $\det(a_i^{m_j}) = 0$, since two columns coincide.
\end{lemma}

\begin{lemma}\label{lem:minsum}
If $m:\{1,\dots,k\}\to\ZZ_{\ge0}$ is injective then $\sum_i m_i\ge N$, with equality if and only if
$\{m_1,\dots,m_k\} = \{0,1,\dots,k-1\}$.
\end{lemma}

\begin{proof}
Induct on the maximum $a$ of the image set $S$.  With $S' = S\setminus\{a\}$ we have
$S'\subseteq\{0,\dots,a-1\}$, so $|S'|\le a$, and by induction
$\sum_{x\in S}x \ge \binom{|S'|}{2}+a \ge \binom{|S'|}{2}+|S'| = \binom{|S|}{2}$.  Equality forces
$a = |S|-1$ and equality for $S'$, whence $S = \{0,\dots,|S|-1\}$.
\end{proof}

\begin{proposition}\label{prop:vanish}
$T_r = 0$ for all $r<N$; consequently $G_d = 0$ for all $d<N$.
\end{proposition}

\begin{proof}
Only injective exponent vectors contribute (Lemma~\ref{lem:noninj}), and these have
$\sum_i m_i \ge N > r$ (Lemma~\ref{lem:minsum}), so the sum in Lemma~\ref{lem:multi} is empty.
Lemma~\ref{lem:falling} then gives $d!\,G_d = 0$.
\end{proof}

\begin{proposition}\label{prop:crit}
$\sfac(k)\,T_N = N!\,V(a)V(b)$, and therefore $\sfac(k)\,G_N = V(a)V(b)$.
\end{proposition}

\begin{proof}
The exponent vectors contributing to $T_N$ are exactly the bijections onto $\{0,\dots,k-1\}$, i.e.
$m = \theta_\tau$ with $\theta_\tau(j) = \tau(j)-1$ for $\tau\in S_k$.  For such $m$ the matrix
$(a_i^{\theta_\tau(j)})$ is the Vandermonde matrix with columns permuted by $\tau$, so its
determinant is $\sgn(\tau)V(a)$; the multinomial coefficient is $N!/\sfac(k)$, independent of
$\tau$; and $\sum_\tau \sgn(\tau)\prod_i b_i^{\theta_\tau(i)} = V(b)$ is the Leibniz expansion of the
transposed Vandermonde matrix of $b$.  Hence $T_N = \frac{N!}{\sfac(k)}V(a)V(b)$.  Applying
Lemma~\ref{lem:falling} at $d = N$, using $c_{N,N} = 1$ and Proposition~\ref{prop:vanish}, gives
$N!\,G_N = T_N$; cancel $N!$.
\end{proof}

\begin{lemma}\label{lem:vand}
If $a_1,\dots,a_k$ are distinct elements of $\{0,\dots,p-1\}$ then $p\nmid V(a)$.
\end{lemma}

\begin{proof}
$p$ prime and $p\mid\prod_{i<j}(a_j-a_i)$ would force $p\mid a_j-a_i$ for some $i<j$, impossible
since $0<|a_j-a_i|<p$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:cheb}]
Suppose $F(\zeta) = 0$.  The minimal polynomial of $\zeta$ over $\QQ$ is the cyclotomic polynomial
$\Phi_p(X) = 1+X+\dots+X^{p-1}$, monic with integer coefficients, so $\Phi_p \mid F$ in $\ZZ[X]$, say
$F = \Phi_p H$.  Shifting, $G(X) = g(X)H(X+1)$ with $g(X) = \Phi_p(X+1)$, whose constant coefficient
is $\Phi_p(1) = p$; thus $g$ has trailing degree $0$ and trailing coefficient $p$.  By
Propositions~\ref{prop:vanish} and~\ref{prop:crit} together with Lemma~\ref{lem:vand}, $G$ has
trailing degree exactly $N$ with trailing coefficient $G_N \ne 0$.  Multiplicativity of trailing
coefficients gives $p \mid G_N$, hence $p \mid \sfac(k)G_N = V(a)V(b)$, contradicting
Lemma~\ref{lem:vand}.
\end{proof}

\begin{remark}
The proof uses nothing about $\zeta$ beyond $\Phi_p(1) = p$.  The identity
$\sfac(k)G_N = V(a)V(b)$ is a purely combinatorial statement about signed sums of binomial
coefficients and can be verified numerically for small $k$.
\end{remark}

\section{The additive uncertainty principle and its exact converse}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Let $A = \supp f$, $\alpha = |A|\ge1$, $B = \supp\hat f$, $\beta = |B|$, and suppose
$\alpha+\beta\le p$.  Then $|B^c| = p-\beta \ge \alpha$; choose $R\subseteq B^c$ with $|R| = \alpha$.
Since $\hat f$ vanishes on $R$ and $f$ vanishes off $A$,
\[
  0 = \hat f(k) = \sum_{x\in A}\zeta^{\overline k\overline x}f(x)\qquad (k\in R),
\]
so $(f(x))_{x\in A}$ lies in the kernel of the square submatrix
$(\zeta^{\overline k\overline x})_{k\in R,x\in A}$, which is invertible by
Theorem~\ref{thm:cheb}.  Hence $f = 0$, a contradiction.
\end{proof}

\begin{proposition}[Extremal examples]
For $p$ prime, the delta $\delta_c$ has $(|\supp f|,|\supp\hat f|) = (1,p)$ and the constant
function $f\equiv1$ has $(p,1)$; both totals equal $p+1$.
\end{proposition}

\begin{proof}
$\widehat{\delta_c}(k) = \zeta^{\overline k\overline c}$ never vanishes; and
$\sum_x\zeta^{\overline k\overline x}$ equals $p$ for $k = 0$ and $0$ otherwise.
\end{proof}

\begin{theoremletter}[Exact converse]\label{thm:C}
Let $p$ be prime and let $A,B\subseteq\Zp$ satisfy $|A|+|B| = p+1$.  Then there is
$f:\Zp\to\CC$ with $\supp f = A$ and $\supp\hat f = B$.
\end{theoremletter}

\begin{proof}
Write $\alpha = |A|$, $\beta = |B|$, so $|B^c| = \alpha-1$.  The map
$\Psi(f) = (\hat f(k))_{k\in B^c}$ on signals supported in $A$ is given by the
$(\alpha-1)\times\alpha$ matrix $(\zeta^{\overline k\overline x})_{k\in B^c,x\in A}$, all of whose
$(\alpha-1)\times(\alpha-1)$ minors are nonzero by Theorem~\ref{thm:cheb}; hence it has full row
rank and $\ker\Psi$ is one-dimensional.  Let $f$ span it.  If $f(x_0) = 0$ for some $x_0\in A$, then
$f$ restricted to $A\setminus\{x_0\}$ would be a nonzero kernel vector of an invertible square
submatrix, impossible; so $\supp f = A$.  By construction $\supp\hat f\subseteq B$, and a strict
inclusion would give $|\supp f|+|\supp\hat f|\le\alpha+\beta-1 = p$, contradicting
Theorem~\ref{thm:A}.
\end{proof}

\begin{corollary}
For every $\alpha$ with $1\le\alpha\le p$ the pair $(\alpha,p+1-\alpha)$ is realised, with supports
placed at arbitrary prescribed sets of those sizes.  Thus no refinement of Theorem~\ref{thm:A}
involving the positions of the supports is possible.
\end{corollary}

\section{Primality is necessary: a criterion}

Let $n = de$ and $\zeta = \zeta_n$.

\begin{definition}
The \emph{subgroup indicator} $u_{n,d}:\Zn\to\CC$ is the indicator of $d\ZZ/n\ZZ = \{x : d\mid\overline x\}$.
\end{definition}

\begin{lemma}
$|\supp u_{n,d}| = e$.
\end{lemma}

\begin{lemma}[Finite Poisson summation]
For all $k$,
\[
  \widehat{u_{n,d}}(k) \;=\; \sum_{j=0}^{e-1}\big(\zeta^{\overline k d}\big)^j
  \;=\; \begin{cases} e, & e \mid \overline k,\\ 0,&\text{otherwise.}\end{cases}
\]
Consequently $|\supp\widehat{u_{n,d}}| = d$: the transform of a subgroup indicator is a multiple of
the indicator of its annihilator.
\end{lemma}

\begin{proof}
Put $w = \zeta^{\overline kd}$.  Then $w = 1$ iff $n\mid\overline kd$ iff $e\mid\overline k$, in
which case the sum is $e$; otherwise $w^e = \zeta^{\overline k n} = 1$ and $w \ne 1$, so the
geometric sum $(w^e-1)/(w-1)$ vanishes.
\end{proof}

\begin{theoremletter}[Primality criterion]\label{thm:D}
Let $n\ge2$.  The bound $|\supp f|+|\supp\hat f| \ge n+1$ holds for every nonzero $f:\Zn\to\CC$ if
and only if $n$ is prime.
\end{theoremletter}

\begin{proof}
Sufficiency is Theorem~\ref{thm:A}.  If $n = de$ with $d,e\ge2$, the nonzero function $u_{n,d}$
satisfies $|\supp u_{n,d}|+|\supp\widehat{u_{n,d}}| = e+d \le de = n < n+1$, since
$(d-1)(e-1)\ge1$.
\end{proof}

\begin{remark}
The deficit is exactly $(d-1)(e-1)$, maximal for balanced factorisations; there the multiplicative
bound is tight, $d\cdot e = n$.  For $n = 4$: $f = (1,0,1,0)$ has $\hat f = (2,0,2,0)$, supports of
size $2$ each, total $4 < 5$ and product $4 = n$.
\end{remark}

\section{Linear-algebraic consequences}

Throughout, $p$ is prime.  For $A,B\subseteq\Zp$ let $M_{A,B}$ be the $|B|\times|A|$ matrix with
entries $\zeta^{\overline k\overline x}$, $k\in B$, $x\in A$.

\begin{theoremletter}[Fourier interpolation]\label{thm:E}
Let $A,B\subseteq\Zp$ with $|A| = |B|$ and let $g:B\to\CC$ be arbitrary.  Then there is exactly one
$f:\Zp\to\CC$ vanishing off $A$ with $\hat f(k) = g(k)$ for all $k\in B$.
\end{theoremletter}

\begin{proof}
The conditions form the square system $M_{A,B}(f(x))_{x\in A} = (g(k))_{k\in B}$, and $M_{A,B}$ is
invertible by Theorem~\ref{thm:cheb}.
\end{proof}

\begin{corollary}
If $|B|\le|A|$, every prescribed datum on $B$ is matched by some signal supported in $A$.  If
$|A|\le|B|$, a signal supported in $A$ is determined by its transform on $B$.
\end{corollary}

\begin{theoremletter}[Rank of an arbitrary minor]\label{thm:F}
For all $A,B\subseteq\Zp$, $\;\rank M_{A,B} = \min(|A|,|B|)$.
\end{theoremletter}

\begin{proof}
The rank is at most $r := \min(|A|,|B|)$; choosing $A'\subseteq A$, $B'\subseteq B$ of size $r$ makes
$M_{A',B'}$ invertible by Theorem~\ref{thm:cheb}, giving a nonzero $r\times r$ minor.
\end{proof}

\begin{theoremletter}[Zero counting]\label{thm:G}
For $p$ prime and $f\ne0$, $\;\#\{k : \hat f(k) = 0\} < |\supp f|$.
\end{theoremletter}

\begin{proof}
The zero set has size $p-|\supp\hat f| \le |\supp f|-1$ by Theorem~\ref{thm:A}.
\end{proof}

A $k$-sparse signal thus has a spectrum vanishing at most $k-1$ times, exactly as a nonzero
polynomial of degree $k-1$ has at most $k-1$ roots: $\hat f$ is the evaluation at $p$-th roots of
unity of a $k$-term exponential polynomial.

\section{Deterministic sparse recovery}

\begin{theoremletter}[Sparse recovery]\label{thm:H}
Let $p$ be prime and let $f,g$ be $k$-sparse.  If $S\subseteq\Zp$ has $|S|\ge2k$ and
$\hat f|_S = \hat g|_S$, then $f = g$.
\end{theoremletter}

\begin{proof}
Let $h = f-g \ne 0$.  Then $|\supp h|\le2k$ and $\hat h$ vanishes on $S$, so
$|\supp\hat h|\le p-2k$ and the total is at most $p$, contradicting Theorem~\ref{thm:A}.
\end{proof}

The sampling set is \emph{arbitrary}: no randomness, incoherence, or restricted isometry hypothesis
is needed, and the guarantee is exact rather than probabilistic.  The threshold is optimal.

\begin{theoremletter}[Optimality of the threshold]\label{thm:I}
Let $p$ be prime, $1\le k$ with $2k\le p$, and let $S$ be any set of $2k-1$ frequencies.  Then there
are distinct $k$-sparse $f\ne g$ with $\hat f|_S = \hat g|_S$.
\end{theoremletter}

\begin{proof}
Pick $A$ with $|A| = 2k$.  The matrix $M_{A,S}$ has $2k-1$ rows and $2k$ columns, hence a nonzero
kernel vector $h$ supported in $A$; by Theorem~\ref{thm:cheb} all its coordinates are nonzero.
Partition $A = A_1\sqcup A_2$ into halves of size $k$ and set $f = h\mathbf 1_{A_1}$,
$g = -h\mathbf 1_{A_2}$.  Then $f-g = h \ne 0$ and $\hat f-\hat g = \hat h$ vanishes on $S$.
\end{proof}

\subsection{Algorithms}

\begin{algorithmbox}[Support-constrained interpolation]
Given $A,B$ with $|A| = |B| = m$ and data $g$: build $M_{A,B}$, solve $Mc = g$ by Gaussian
elimination with partial pivoting in $O(m^3)$ operations, and return the signal $f$ with
$f|_A = c$, $f = 0$ elsewhere.  Nonsingularity is guaranteed for every pair $(A,B)$.
\end{algorithmbox}

\begin{algorithmbox}[Extremal-pair construction]
Given $A,B$ with $|A|+|B| = p+1$: set $R = \Zp\setminus B$, form the $(|A|-1)\times|A|$ matrix
$M_{A,R}$, and return the signal whose coefficients are the signed maximal minors
$c_x = (-1)^{\mathrm{pos}(x)}\det(M_{A,R}\text{ with column }x\text{ deleted})$.  These lie in the
kernel and all are nonzero by Theorem~\ref{thm:cheb}, so $\supp f = A$ and $\supp\hat f = B$.
\end{algorithmbox}

\begin{algorithmbox}[Deterministic $k$-sparse recovery]
Given $|S|\ge2k$ and $y = \hat f|_S$: for each candidate support $A$ of size $k$, solve
$M_{A,S}c = y$ (full column rank $k$ by Theorem~\ref{thm:F}) and test consistency; by
Theorem~\ref{thm:H} exactly one candidate is consistent.  For $S$ an arithmetic progression, Prony's
method with Berlekamp--Massey recovers the support in $O(k^2)$ operations instead of
$\binom pk$ trials.
\end{algorithmbox}

\section{Discussion and future directions}

Both bounds constrain the achievable region of pairs $(|\supp f|,|\supp\hat f|)$: the multiplicative
bound gives the hyperbolic region $\alpha\beta\ge p$, the additive bound the strictly smaller
half-plane $\alpha+\beta\ge p+1$, whose boundary is entirely attained by Theorem~\ref{thm:C}.  Every
obstruction in the composite case is a subgroup, because the transform of a subgroup indicator is
supported on its annihilator; prime cyclic groups admit no such hiding place, which is exactly what
Theorem~\ref{thm:D} formalises.

Frenkel's argument combines three ideas: deformation (replace $\zeta$ by a variable, turning a
vanishing determinant into a divisibility in $\ZZ[X]$); order of vanishing (the shift
$X\mapsto X+1$ places the point of interest at the origin, and distinctness of surviving multinomial
exponents forces vanishing to order $\binom k2$); and identification of the critical jet as a
Vandermonde product that $p$ cannot divide.

Open directions include: quantitative conditioning of $M_{A,B}$ (Chebotarev gives invertibility but
no uniform lower bound on the smallest singular value, which is what noise-robust recovery needs);
the sharp support inequality on a general finite abelian group, presumably of the form
$|\supp f|+|\supp\hat f| \ge \min_H(|H|+[G:H])$ over admissible subgroups; polynomial-time recovery
from an \emph{arbitrary} set of $2k$ frequencies; classification of the nonsingular minors of a
general character table; and structured refinements of the zero-counting theorem for supports with
arithmetic structure.

\section*{Summary of main results}
\begin{enumerate}
\item Every square submatrix of the prime-order Fourier matrix is invertible.
\item $|\supp f|+|\supp\hat f|\ge p+1$ for nonzero $f$ on $\Zp$, strictly stronger than
$|\supp f|\cdot|\supp\hat f|\ge p$.
\item Every pair $A,B$ with $|A|+|B| = p+1$ occurs as $(\supp f, \supp\hat f)$.
\item The additive bound characterises primality among moduli $n\ge2$.
\item $\rank M_{A,B} = \min(|A|,|B|)$, with unique interpolation in the square case.
\item $\hat f$ vanishes at fewer than $|\supp f|$ frequencies.
\item $k$-sparse signals are determined by any $2k$ frequencies, and $2k-1$ never suffice.
\end{enumerate}

